TP.register({id:"lp5-g1",lp:5,grade:"1",mode:"curriculum",checks:4,nextGrade:"2nd grade",build(E){const F=E.F;const TENT="tent",DOG="dog",FLAG="flag",CRATE="box",SKY="star",SKI="skis",BOOT="boot",RADIO="radio",THERM="thermometer",SNOW="snowflake",FISH="fish";const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const K_WELD=window.TP_ICON_WELD||((parts,st)=>parts.map(f=>f(st)).join("")+parts.map(f=>f('stroke="none"')).join(""));const at=(x,y,k,inner)=>`<g transform="translate(${x} ${y}) scale(${k})">${inner}</g>`;const kface=(x,y,k,sp,mw)=>at(x,y,k,K_FACE(0,0,sp,mw||4));const eyeAt=(x,y,k,r)=>at(x,y,k,K_EYE(0,0,r));const blushAt=(x,y,k)=>at(x,y,k,K_BLUSH(0,0));const INK="#6B4A3C",FUR="#C2C7CE",FUR_L="#E8EBEF",WOOD="#E7C49A",STEEL="#CBD8E2";function sealPic(w){return`<svg viewBox="0 0 ${w} ${Math.round(w*.66)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a seal">${window.TP_P5.fit("seal",w/2,w*.33,w,w*.66)}</svg>`}function sledPic(w){return`<svg viewBox="0 0 ${w} ${Math.round(w*.62)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a sled">${window.TP_P5.fit("sled",w/2,w*.31,w,w*.62)}</svg>`}const CAMP="Our camp sits on thick ice. We sleep in red tents. The sun is up all day. It is up all night too. Six big dogs pull our sled. They run fast on the hard snow. We pack the sled with food. We pack a radio too. Then we ski up a long hill. At the top we put a flag. The flag stands in the snow. It shows the way back to camp. We eat hot soup. We sit in the big tent.";const HAT="Rosa and Pim work at a camp out on the ice. One windy day, the wind took Pim's red hat and blew it away. “My hat!” Pim cried. Rosa ran to help him look. They dug through the soft snow by the tents. At last Pim found his hat. It was under a crate, which is a big box that holds camp food. Pim brushed off the snow and put the hat on his head. Then he sat down to rest, warm and happy.";const SEALS="A seal lives in the cold sea. It has a thick layer of fat, and the fat keeps it warm. A seal can hold its breath for a long time. It swims down deep to find fish. When it needs to breathe, it comes up to a hole in the ice, because that is where it can get air. After a big meal, seals like to rest on flat ice in the sun.";const LIGHTS="On some winter nights, the sky near the North Pole glows green and pink. People call this the northern lights. The light comes from tiny bits of energy that fly off the sun. The bits hit the air high above the ground and make it glow. The lights can look like curtains that wave and bend. The best time to see them is on a dark, clear night far away from city lights. Scientists at polar camps watch the lights and write down what they see.";const ICETHICK="The team drilled a hole in the ice to measure how thick it was. The ice near camp was almost three feet thick, strong enough to hold the heavy sleds. Farther out, the ice was thinner and cracked into floating pieces called floes. The leader marked the thin ice with orange flags so nobody would drive a sled that way.";const WORDS=["thin","neck","swim","pass","cave","note","seal","deep","fur","jumped","sunset","vope"];function story(title,text){return`<p class="big" style="text-align:center;margin:0 0 6px">${title}</p><p class="passage">${text}</p>`}function emo(e,size){return`<span style="font-size:${size||"3.4rem"};line-height:1" aria-hidden="true">${ic(e,Math.round(parseFloat(size||"3.4rem")*16))}</span>`}function circleHalves(){return`<svg viewBox="0 0 160 160" width="160" role="img" aria-label="Circle cut into two equal parts by one line, one part shaded"><circle cx="80" cy="80" r="70" fill="var(--surface)" stroke="var(--ink)" stroke-width="3"/><path d="M80 10 A70 70 0 0 0 80 150 Z" fill="var(--gold)" stroke="var(--ink)" stroke-width="3"/><line x1="80" y1="10" x2="80" y2="150" stroke="var(--ink)" stroke-width="3"/></svg>`}function rectFourths(){return`<svg viewBox="0 0 200 120" width="200" role="img" aria-label="Rectangle cut into four equal parts, one part shaded"><rect x="4" y="4" width="192" height="112" fill="var(--surface)" stroke="var(--ink)" stroke-width="3"/><rect x="4" y="4" width="96" height="56" fill="var(--gold)" stroke="var(--ink)" stroke-width="3"/><line x1="100" y1="4" x2="100" y2="116" stroke="var(--ink)" stroke-width="3"/><line x1="4" y1="60" x2="196" y2="60" stroke="var(--ink)" stroke-width="3"/></svg>`}function circleUneven(){return`<svg viewBox="0 0 160 160" width="160" role="img" aria-label="Circle cut into two parts that are not the same size"><circle cx="80" cy="80" r="70" fill="var(--surface)" stroke="var(--ink)" stroke-width="3"/><path d="M38 24 A70 70 0 0 0 38 136 Z" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="3"/><line x1="38" y1="24" x2="38" y2="136" stroke="var(--ink)" stroke-width="3"/></svg>`}function sharesFig(){return F.row([circleHalves(),"Shape A"],[rectFourths(),"Shape B"],[circleUneven(),"Shape C"])}function packList(){return F.table(["What we packed","What it is for"],[[`${emo(RADIO,"2rem")} a radio`,"to call the ship for help"],[`${emo(TENT,"2rem")} a tent`,"to sleep out of the wind"],[`${emo(CRATE,"2rem")} 8 boxes of food`,"to eat, 1 box each day"],[`${emo(BOOT,"2rem")} warm boots`,"to keep your feet dry on the ice"]],{caption:"Sled Pack List"})}function unitRowFig(){const U=48,blk=(x,y)=>`<rect x="${x}" y="${y}" width="${U}" height="24" fill="var(--gold)" stroke="var(--gold-ink)" stroke-width="2"/>`;let s=`<svg viewBox="0 0 480 214" width="460" role="img" aria-label="A ski with seven same-size blocks laid end to end under it, and a rope with four of the same blocks under it.">`;s+=`<rect x="40" y="28" width="${7*U}" height="16" rx="8" fill="var(--sea)" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<7;i++)s+=blk(40+i*U,52);s+=`<text x="414" y="40" font-size="22" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle">ski</text>`;s+=`<rect x="40" y="118" width="${4*U}" height="14" rx="7" fill="var(--sea)" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<4;i++)s+=blk(40+i*U,140);s+=`<text x="276" y="130" font-size="22" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle">rope</text>`;s+=`<text x="40" y="200" font-size="19" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)">Every block is the same size.</text>`;return s+`</svg>`}const TWO=`<ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul>`;const WDIR="Write on your paper. When you finish, hold it up and read it to your teacher.";const STOPS=[{id:1,title:"Ice Camp Sounds",short:"Ice Sounds",parts:[{std:["RF.1.2"],n:6,dur:70,dir:"Listen to your teacher. Say the sounds and words out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic("ear",96)} ${ic(SNOW,96)}</p><p class="big" style="text-align:center">Listen. Then say it.</p>`,key:["Blend these sounds: /f/ /l/ /a/ /g/ (flag)","Blend these sounds: /s/ /k/ /ē/ (ski)","Clap the word parts in snowflake. How many parts? (2 parts: snow and flake)","What is the last sound in ice? (/s/)","Say all the sounds in snow. (/s/ /n/ /ō/, three sounds)","Which word has a long vowel sound: seal or shell? (seal)"],desc:"blending, segmenting, and isolating sounds, counting syllables, and telling long from short vowels in spoken words"}]},{id:2,title:"Flag Hops",parts:[{std:["1.OA.C.5"],dur:90,dir:"Count out loud like you are hopping from flag to flag. Say each answer.",html:()=>`<p class="huge" style="font-size:3rem;margin:4px 0" aria-hidden="true">${ic(FLAG,48)} ${ic(FLAG,48)} ${ic(FLAG,48)}</p><p class="small" style="text-align:center">The team puts a flag in the snow to mark the way back to camp.</p>`,qs:["Start at 8. Count on 5. Where do you land? What adding sentence is that?","Start at 16. Count back 4. Where do you land? What take away sentence is that?","Solve 2 + 9 by counting on. Which number is faster to start at? Say the numbers you count.","Solve 13 - 10. Start at 10 and count up to 13. How many hops is that?","True or silly? To solve 15 - 2, Rosa counts 15, 14 and says the answer is 14."],key:["Counts 9, 10, 11, 12, 13. Lands on 13. 8 + 5 = 13","Counts 15, 14, 13, 12. Lands on 12. 16 - 4 = 12","Starts at 9. Counts 10, 11. Answer 11","Counts 11, 12, 13. That is 3 hops, so 13 - 10 = 3","Silly. The first number is not a hop. Count back two hops: 14, 13. The answer is 13"],desc:"counting on and counting back or up to add and subtract"}]},{id:3,title:"Base Camp Words",short:"Camp Words",parts:[{std:["RF.1.3"],kind:"words",words:WORDS,wordPics:1,n:12,dur:95,dir:"Read each word out loud. The last one is a silly word. Just sound it out.",key:["Count each word read correctly. vope is a silly word: listen for the long o that the final e makes.","Watch for: th (thin), ck ending (neck), blend (swim), double letters (pass), final e (cave, note), vowel teams (seal, deep), r-controlled ur (fur), the -ed ending said as /t/ (jumped), two syllables (sunset)."],desc:"reading words with digraphs, blends, final e, vowel teams, r-controlled vowels, endings, and two syllables"}]},{id:4,title:"Crate Count",short:"Crates",parts:[{std:["1.NBT.A.1"],n:4,dur:85,dir:"Count and read out loud. Write your numbers on your paper and hold it up.",html:()=>`<p class="small" style="text-align:center">Supplies come to camp in crates. A crate is a big box.</p>`,qs:["Count out loud from 96 to 112.","Read these numbers out loud: 58, 103, 119.","Write the number one hundred seven.","Count the crates in the picture. Write the number that tells how many."],fig2:()=>F.row(F.objects(CRATE,14,7)),key:["96, 97, 98, 99, 100, 101 ... 112. Watch the jump past 99","Fifty-eight, one hundred three, one hundred nineteen","107, not 1007","14"],desc:"counting, reading, and writing numerals to 120 and counting objects"}]},{id:5,title:"Camp on the Ice",short:"Camp Read",parts:[{std:["RF.1.4"],kind:"read",n:75,label:"words read correctly",dur:90,dir:"Look at the three pictures. Then read the story out loud in your best reading voice.",html:()=>`${F.row(F.pic(TENT,"tents at camp","3.6rem"),F.pic(DOG,"dogs that pull a sled","3.6rem"),F.pic(FLAG,"a flag marks the way","3.6rem"))}${story("Camp on the Ice",CAMP)}`,key:["75 words, not counting the title. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Point to the three pictures first so tents, sled dogs, and flag are clear before the student reads.","Note pace, expression, and whether the student rereads to fix a mistake.","Quick check after reading: What do the dogs do? (pull the sled)"],desc:"a 75-word polar story read aloud"}]},{id:6,title:"Sled Load Problems",short:"Sled Loads",parts:[{std:["1.OA.A.1"],dur:140,dir:"Listen to each story problem. You can draw on your paper. Say your answer.",html:()=>`<p class="huge" style="font-size:3rem;margin:0" aria-hidden="true">${sledPic(130)} ${ic(CRATE,48)} ${ic(CRATE,48)}</p><p class="small" style="text-align:center">A sled is pulled over the snow. Boxes and bags on the sled hold the camp food.</p>`,qs:["The team packs 8 boxes of food on one sled and 7 boxes on the other sled. How many boxes in all?","There were 13 bags of dog food. The dogs ate 5 bags. How many bags are left?","Rosa skied 6 miles. Pim skied 13 miles. How many more miles did Pim ski?","There are 16 flags. 7 flags are already in the snow. The rest are still on the sled. How many flags are on the sled?","Some seals rested on the ice. Then 4 more seals came up. Now there are 12 seals. How many seals were there at the start? Write a number sentence with a box and hold it up."],key:["15 boxes (8 + 7 = 15)","8 bags (13 - 5 = 8)","7 more miles (13 - 6 = 7 or 6 + 7 = 13)","9 flags (7 + 9 = 16 or 16 - 7 = 9)","8 seals. Writes □ + 4 = 12 or 12 - 4 = □"],desc:"addition and subtraction word problems within 20, with the unknown in different places"}]},{id:7,title:"The Hat in the Wind",short:"The Hat",parts:[{std:["RL.1.1"],dur:95,dir:"Read the story out loud. Then listen to each question and answer out loud.",html:()=>story("The Hat in the Wind",HAT),qs:["What did Pim lose?","Who ran to help Pim look?","Where did Pim find it?","What is a crate?","Ask me a question about the story."],key:["His red hat. The wind took it","Rosa","Under a crate, in the snow near the tents","A big box that holds the camp food","Asks a real question about the story, such as: Why was the wind so strong? If stuck, say: Start with who, what, or where."],desc:"asking and answering key detail questions about a story the student read"}]},{id:8,title:"Smart Adding",short:"Smart Add",parts:[{std:["1.OA.B.3"],dur:120,dir:"Answer out loud. Tell how you know.",html:()=>`<p class="huge" style="font-size:3rem;margin:4px 0" aria-hidden="true">${ic(CRATE,48)} ${ic(CRATE,48)} ${ic(CRATE,48)}</p>`,qs:["7 + 8 = 15. So what is 8 + 7?","Pim says 6 + 9 is easier if he turns it around and thinks 9 + 6. Is that OK? What is the total?","Add 4 + 6 + 9. Which two numbers would you add first? Why?","Add 5 + 2 + 8.","Make a ten to solve 8 + 5. Break the 5 into 2 and 3."],key:["15. Knows it without counting because the two numbers just switch places","Yes, that is fine. The order does not change the total. Both make 15","19. Adds 4 + 6 to make 10, then 10 + 9","15. Adds 2 + 8 to make 10, then 10 + 5","13. 8 + 2 = 10, then 10 + 3 = 13"],desc:"using turn-around facts and making ten as strategies to add"}]},{id:9,title:"Seals on the Ice",short:"Seals",parts:[{std:["RI.1.1"],dur:90,dir:"Read about seals out loud. Then listen to each question and answer out loud.",html:()=>`<p style="text-align:center;margin:0">${sealPic(140)} ${emo(FISH,"3rem")}</p>${story("Seals",SEALS)}`,qs:["What keeps a seal warm?","What does a seal swim down deep to find?","Why does a seal come up to a hole in the ice?","Where do seals rest?","Ask me one question about seals."],key:["Its thick fat","Fish","To get air","On flat ice in the sun","Asks a real question about seals, such as: How big do they get? If stuck, say: Start with what, how, or why."],desc:"asking and answering key detail questions about an informational text the student read"}]},{id:10,title:"Split It Even",short:"Split Even",parts:[{std:["1.G.A.3"],n:6,dur:110,dir:"Look at the shapes. Answer out loud. Draw the last one on your paper.",fig:()=>sharesFig(),qs:["Shape A is cut into 2 equal parts. What do we call the shaded part?","Look at Shape B. How many equal parts is it cut into? What do we call one of those parts?","Shape C is cut into 2 parts. Are they halves? Tell why or why not.","Shape A is cut into 2 equal parts. How many of those parts make the whole circle, and what do we call them?","Shape B is cut into 4 equal parts. If we cut that same rectangle into only 2 equal parts instead, would each part be bigger or smaller than one part you see now? Why?","Draw a rectangle on your paper. Cut it into 2 equal parts. Shade one part. Hold it up."],key:["One half, or half of the circle","4 equal parts. One part is a fourth, or a quarter","No. The 2 parts are not the same size, so they are not halves","Two of them make the whole circle. We call them halves","Bigger. Cutting a whole into fewer equal parts makes each part bigger","Draws a rectangle cut into 2 parts that are about the same size, with one part shaded"],desc:"halves and fourths of circles and rectangles"}]},{id:11,title:"Flag Line Sentences",short:"Sentences",parts:[{title:"Sentence Spotter",std:["RF.1.1"],dur:50,dir:"Look at the sentences. Answer out loud.",html:()=>`<p class="passage" style="text-align:center">The dogs pull the sled. Can you see the flag?</p>`,qs:["How many sentences do you see? How can you tell?","Read the first word of the second sentence. What kind of letter does it start with?","What is the mark at the end of the second sentence called? What does it tell you?","Spot the mistake. Look at the words in the box. What 2 things need to be fixed?"],fig2:()=>`<div class="figure"><p class="passage" style="border:3px dashed var(--line);border-radius:16px;padding:10px 26px;margin:0">the ice is thick</p></div>`,key:["2 sentences. Each one starts with a capital letter and ends with an end mark","The word is Can. It starts with a capital, or uppercase, C","A question mark. It tells you the sentence asks something","The first word needs a capital letter, and the sentence needs a period at the end"],desc:"finding sentences by their first word, capital letter, and end mark"},{title:"Camp Fix It",std:["L.1.1"],dur:70,dir:"Listen to your teacher read each one. Say your answer out loud.",qs:["Which sounds right? The dog pull the sled. Or: The dogs pull the sled.","One tent, two ____.","We saw a seal. ____ was on the ice. (It or Them)","Finish it so it tells when: We ski ____ the sun comes up.","Add a word that tells more about the wind: The ____ wind blows hard.","Which sounds right? Rosa and Pim is cold. Or: Rosa and Pim are cold."],key:["The second one. More than one dog goes with the verb pull","tents","The first choice, It, because one seal is a thing","Any word that tells when and fits, such as after, before, or when","Any describing word that fits, such as cold, icy, or strong","The second one. Two people go with the verb are"],desc:"spoken grammar items (plural nouns, subject and verb match, pronouns, time words, describing words)"}]},{id:12,title:"Northern Lights Chat",short:"Sky Chat",parts:[{title:"Sky Lights Listen",std:["SL.1.2"],n:4,dur:75,read:LIGHTS,dir:"Listen carefully. Your teacher will read about lights in the night sky. Then answer out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(SKY,96)}</p><p class="big" style="text-align:center">Listen.</p>`,key:["Ask: What two colors glow in the sky? (green and pink)","Ask: Where does the light come from? (tiny bits of energy from the sun)","Ask: What can the lights look like? (curtains that wave and bend)","Say: Ask me one question about the northern lights. (asks 1 question that is about what was read and starts with a question word, such as: When can you see them?)"],desc:"asking and answering questions about a text read aloud"},{title:"Tell Me About It",std:["SL.1.4"],n:3,label:"checks met",dur:60,dir:"Talk for about one minute. Speak clearly.",html:()=>`<p class="big">Tell me about something you wear or use when you are cold.</p><ul class="qlist" style="margin-top:14px"><li>What is it?</li><li>What does it look like?</li><li>How does it help you?</li></ul>`,key:["Names the thing and gives 2 or more details about it (SL.1.4)","Gives 2 or more details about what it looks like, and they stay on this one thing (SL.1.4)","Says how it helps and how they feel about it, in at least 1 complete sentence (SL.1.4)"],desc:"describing a thing with relevant details"}]},{id:13,title:"Radio Call",short:"Radio",parts:[{std:["W.1.8"],n:3,label:"checks met",dur:80,dir:"Look at the chart. Write 1 sentence on your paper and hold it up.",html:()=>`<p class="big">The team is far out on the ice and needs help from the ship. What will they use? Use the chart.</p>`,fig:()=>packList(),key:["Finds the answer in the chart. Your help is fine: read the two columns out loud and point to the first row","Writes a sentence drawn from the chart, such as: They will use the radio","The answer fits the question. It names the one item on the list that is for calling the ship"],desc:"using a provided chart to answer a question in writing"}]},{id:14,title:"Camp Journal",short:"Write",parts:[{wk:"opinion",alt:{group:"write",label:"Dogsled or Skis",icon:"🐕",hint:"Tell what you think and why"},std:["W.1.1"],n:4,label:"checks met",dur:200,dir:WDIR,html:()=>`<p class="big">Would you rather cross the snow on a dogsled or on skis? Write what you think and tell why.</p><div class="figure">${F.pic(DOG,"a dogsled team","3.6rem")}${F.pic(SKI,"skis","3.6rem")}</div>${TWO}`,key:["Names the topic: riding a dogsled or going on skis (W.1.1)","States an opinion, which one the student would pick (W.1.1)","Gives at least one reason for the opinion, such as it is faster or quieter (W.1.1)","Gives some sense of closure, such as: That is why I would pick it (W.1.1)"],desc:"an opinion piece about a dogsled or skis"},{wk:"facts",alt:{group:"write",label:"Polar Camp Facts",icon:"⛺",hint:"Tell 2 facts about a polar camp"},std:["W.1.2"],n:3,label:"checks met",dur:200,dir:WDIR,html:()=>`<p class="big">Write about a polar camp. Tell 2 facts about it. The pictures can help.</p><div class="figure">${F.pic(TENT,"tents keep out the wind","3.4rem")}${F.pic(DOG,"dogs pull the sleds","3.4rem")}${F.pic(THERM,"colder than a freezer","3.4rem")}</div>${TWO}`,key:["Names the topic: a polar camp (W.1.2)","Gives at least 2 facts, such as people sleep in tents, dogs pull the sleds, or the air is very cold (W.1.2)","Gives some sense of closure, such as: That is what a polar camp is like (W.1.2)"],desc:"an informative piece with facts about a polar camp"}]},{id:15,title:"Tens and Ones",short:"Tens",parts:[{std:["1.NBT.B.2"],n:3,dur:55,dir:"Look at the blocks. Answer out loud.",fig:()=>F.row(F.tens(4,7)),qs:["Each tall bar is one ten and each little square is one. What number do the blocks show?","In the number 53, what does the 5 stand for?","How many tens and how many ones are in 70?"],key:["47. Four tens and seven ones","5 tens, which is 50","7 tens and 0 ones"],desc:"reading a two-digit number as tens and ones"}]},{id:16,title:"Loading Up",short:"Add Tens",parts:[{std:["1.NBT.C.4"],n:3,dur:60,dir:"Solve on your paper. Say your answer and tell how you got it.",html:()=>`<p class="huge" style="font-size:3rem;margin:4px 0" aria-hidden="true">${ic(CRATE,48)} ${sledPic(110)}</p><p class="small" style="text-align:center">More crates come to camp and go on the sled.</p>`,qs:["There were 24 crates at camp. The plane brought 8 more. How many crates now?","There were 35 crates at camp. The plane brought 20 more. How many crates now?","Solve 47 + 6. Tell me how you made a ten to do it."],key:["32 crates. 24 + 8 = 32. Adding the ones makes 12, so a new ten is made","55 crates. 35 + 20 = 55. Three tens plus two tens is five tens, and the 5 ones stay","53. 47 + 3 = 50, then 50 + 3 = 53. Any clear place value or make-a-ten explanation counts"],desc:"adding within 100, including a two-digit number plus ones and plus a multiple of ten"}]},{id:17,title:"Taking Tens Off",short:"Take Tens",parts:[{std:["1.NBT.C.6"],n:3,dur:50,dir:"Answer out loud. Tell how you know.",html:()=>`<p class="huge" style="font-size:3rem;margin:4px 0" aria-hidden="true">${ic(CRATE,48)} ${ic(CRATE,48)}</p><p class="small" style="text-align:center">Crates leave camp ten at a time.</p>`,qs:["60 crates were at camp. 20 crates went out on sleds. How many crates are left?","90 - 40 = ?","Solve 70 - 30 and tell me the answer in tens."],key:["40 crates. 6 tens take away 2 tens is 4 tens","50","40. Seven tens take away three tens is four tens, which is 40"],desc:"subtracting a multiple of ten from a multiple of ten"}]},{id:18,title:"Block Long",short:"How Long",parts:[{std:["1.MD.A.2"],n:3,dur:55,dir:"Look at the blocks under the ski and the rope. Answer out loud.",fig:()=>unitRowFig(),qs:["How many blocks long is the ski?","How many blocks long is the rope?","Why do the blocks have to touch each other, with no gaps and no overlaps?"],key:["7 blocks","4 blocks","Because a gap or an overlap makes the count wrong. The blocks have to span the whole thing end to end for the number to tell the length"],desc:"measuring length as a whole number of same-size units laid end to end"}]},{id:19,title:"Camp Clocks",short:"Clocks",parts:[{std:["1.MD.B.3"],n:3,dur:55,dir:"Look at the two clocks. Answer out loud. Write the last one on your paper.",fig:()=>F.row([F.clock(3,0,190),"Clock A"],[F.clock(7,30,190),"Clock B"]),qs:["What time does Clock A show?","What time does Clock B show?","Write Clock B's time the way a digital clock would show it."],key:["3 o'clock, or 3:00","Half past 7, or 7:30. The hour hand sits between the 7 and the 8, which tells you the hour is still 7","7:30"],desc:"telling and writing time to the hour and the half hour on analog and digital clocks"}]},{id:20,title:"What We Saw",short:"Chart",parts:[{std:["1.MD.C.4"],n:3,dur:60,dir:"Look at the graph. Answer out loud.",fig:()=>F.barGraph({title:"What we saw this week",cats:["seals","fish","birds"],vals:[8,5,4],max:8,step:1}),qs:["How many animals did the team see in all?","How many more seals than birds did they see?","Which one did they see the fewest of, and how many?"],key:["17. 8 seals plus 5 fish plus 4 birds","4 more. 8 seals take away 4 birds","Birds, 4 of them"],desc:"reading a bar graph with three categories: total, how many in each, and how many more"}]},{id:21,title:"Trail Story",short:"Story",parts:[{wk:"story",std:["W.1.3"],n:4,label:"checks met",dur:75,dir:WDIR,html:()=>`<p class="big">Write a story about one day at the ice camp. Tell 2 things that happened, in the order they happened.</p><div class="figure">${F.pic(TENT,"the tents","3.4rem")}${F.pic(FLAG,"the trail flags","3.4rem")}</div>${TWO}`,key:["Tells 2 or more things that happened, in an order that makes sense (W.1.3)","Adds some detail about what happened, such as what it looked like or who was there (W.1.3)","Uses at least one time word to show the order, such as first, then, next, or after that. If none appears, ask once: Which one happened first? (W.1.3)","Gives some sense of closure, such as: Then we went back to the tent (W.1.3)"],desc:"a narrative about a day at camp with two sequenced events, detail, a time word, and closure"}]},{id:22,title:"Copy a Seal Flipper",short:"Copy a Part",parts:[{std:["1-LS1-1"],n:3,dur:90,dir:"Look at the pictures. Answer the first out loud. Draw the second on your paper and hold it up.",desc:"naming the job an animal body part does, then designing a tool that copies it to solve a human problem",html:()=>`<p class="big">A seal moves fast through the water. It has flippers. They are wide, flat and smooth. One sweep of a flipper pushes water. It pushes a lot of water. It goes back at once.</p>
     <div class="figure">${ic("seal",104)}${ic("wave",88)}</div>
     <p class="big">The team has to move a boat. It is a small boat. It goes along a channel. The channel is in the ice. Cupped hands barely move it at all.</p>`,qs:["Why does a wide flat flipper push a boat or a body through water better than a thin one?","Draw a paddle for the team that copies the shape of the seal's flipper.","Tell me which animal part you copied and how the shape of your paddle moves more water."],key:["It pushes against more water at once. A thin shape slips through the water instead of pushing it. Any answer about catching or pushing more water counts.","Any paddle drawn wide and flat on the end: an oar with a broad blade, a flat board on a handle, a spoon shape. A thin stick is partial, so ask what a flipper looks like.","Needs both halves: names the wide flat flipper as the part copied, and says a bigger flat surface pushes more water back, so the boat goes forward further."]}]},{id:23,title:"Penguin Parents",short:"Parents",parts:[{std:["1-LS1-2"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"finding a pattern in what a parent animal does and what the young do in answer, and saying how it helps the young",read:"Near the camp a crowd of penguins stands on the ice. Two parents take turns with one chick. While one parent stands with the chick tucked against its warm feet, the other walks a long way to the water and comes back with food. When the walking parent returns it stops at the edge of the crowd and calls. Among hundreds of chicks, this one chick answers with a whistle of its own, and the parent walks straight to it. Then the two parents swap, and the one that stayed goes off to the water.",qs:["What do the two parents take turns doing?","What does the chick do when the returning parent calls?","Hundreds of chicks stand in that crowd. How does the calling and answering help this parent and this chick find each other?"],key:["One stays and keeps the chick warm on its feet while the other walks to the water for food, and then they swap. Both halves count.","It answers with a whistle of its own.","Each chick has its own voice and each parent knows it, so the right pair find each other in a crowd. Any answer about knowing each other's call counts."]},{std:["1-LS3-1"],n:3,dur:75,dir:"Look at the pictures. Answer out loud.",desc:"making observations that young plants and animals are like their parents but not exactly like them",html:()=>`<p class="big">A penguin chick and a grown penguin. A young seal and the seal that is its parent.</p>
     <div class="figure">${ic("penguin",92)}${ic("penguin",116)}</div>
     <div class="figure">${ic("seal",92)}${ic("seal",116)}</div>`,qs:["Name one way the penguin chick is like the grown penguin.","The chick is covered in soft gray fluff and the grown penguin has smooth black and white feathers. Does that mean the chick is not a penguin? Say why.","The young seal is shorter than its parent and has a lighter coat. Name one thing about the young seal that is the same as its parent."],key:["Both have two feet, a beak, wings held close, and both stand upright. Any likeness counts.","No. It is a penguin, and it is like its parent in the big ways, but young animals are not exactly like their parents. The fluff will be replaced by feathers as it grows.","The same shape of body, the same flippers, the same whiskers, both live in the water and on the ice. Any real sameness counts."]}]},{id:24,title:"The Star Over Camp",short:"Sky Patterns",parts:[{std:["1-ESS1-1"],n:4,dur:90,dir:"Look at the log. Answer out loud.",desc:"finding a pattern in a log of sky observations and using it to predict what comes next",html:()=>`<p class="big">On four clear nights the team looked for one bright star and wrote down where it was.</p>
     <table class="bigTable"><tr><th>Night</th><th>At nine at night</th><th>At midnight</th></tr>
     <tr><td>first night</td><td>over the north marker</td><td>over the north marker</td></tr>
     <tr><td>second night</td><td>over the north marker</td><td>over the north marker</td></tr>
     <tr><td>third night</td><td>over the north marker</td><td>over the north marker</td></tr>
     <tr><td>fourth night</td><td>over the north marker</td><td>over the north marker</td></tr></table>
     <div class="figure">${ic("star",84)}${ic("tent",84)}${ic("telescope",84)}</div>`,qs:["Where was the bright star at nine at night on all four nights?","Did it move between nine at night and midnight?","Tomorrow night is clear. Where do you predict the star will be, and how do you know?","Why is a star that stays in one place useful to a team walking at night?"],key:["over the north marker","No. The log shows it in the same place at both times on every night.","over the north marker again. It has not moved on any of the four nights, so the pattern lets you predict it.","It tells them which way is north, so they can keep going the same way. Any answer about knowing the direction counts."]},{std:["1-ESS1-2"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"relating the number of hours of daylight to the time of year from observations made across a year",html:()=>`<p class="big">Hours of daylight at the camp, counted on one day in each of three months.</p>
     <table class="bigTable"><tr><th>Month</th><th>Hours of daylight</th></tr>
     <tr><td>January</td><td>5</td></tr><tr><td>April</td><td>13</td></tr>
     <tr><td>July</td><td>20</td></tr></table>`,qs:["Which month on the chart had the fewest hours of daylight?","How many more hours of daylight did July have than January?","The team wants to do most of its walking in daylight. Which of these three months should they choose, and how does the chart show it?"],key:["January, 5 hours","15 more hours. 20 take away 5","July, because July has 20 hours of daylight and January has only 5. Far more of the day is light in July."]}]},{id:25,title:"Sound on the Ice",short:"Sound",parts:[{std:["1-PS4-1"],n:4,dur:90,dir:"If you have a rubber band and a cup, try the first part. Either way, answer out loud.",desc:"planning an investigation showing that a shaking material makes sound and that a sound can make a material shake",html:()=>`<p class="big">Stretch a rubber band over the open top of a cup. Pluck it and put a fingertip on it while it sounds.</p>
     <div class="figure">${ic("radio",96)}${ic("tent",96)}</div>
     <p class="big">Now turn the camp radio up and rest your fingers lightly on the front of it. Then sprinkle a few grains of dry rice on top of it.</p>`,qs:["What do you feel on your fingertip while the rubber band is sounding?","Hold the rubber band still. What happens to the sound?","What do your fingers feel on the front of the radio while it is playing?","What do the grains of rice on top of the radio do, and what does that show about sound?"],key:["A buzz or a tickle. The band is shaking back and forth very fast.","The sound stops, because the shaking has stopped. No shaking, no sound.","A buzzing or humming. The front of the radio is shaking.","They hop and dance. It shows that a shaking thing makes sound and that the shaking can pass on and move something else."]}]},{id:26,title:"Inside the Dark Tent",short:"Light",parts:[{std:["1-PS4-2"],n:3,dur:75,dir:"Answer out loud.",desc:"accounting for why an object in darkness can be seen only when light shines on it",html:()=>`<p class="big">In the long dark month the tent flap is tied shut and the lamp is off. No light gets in.</p>
     <div class="figure">${ic("compass",96)}${ic("torch",96)}</div>`,qs:["The compass is lying on the floor of the tent. Can you see it in there? Say why or why not.","What would have to change in that tent before the compass could be seen?","Someone says that if you wait long enough your eyes will see in complete darkness. Is that true? Say what your eyes really need."],key:["No. There is no light in the tent, and a thing can only be seen when light shines on it and comes back to your eyes.","Light has to reach it: the lamp switched on, a flashlight, or the flap opened to let daylight in.","No. Eyes can get used to a little light, but with no light at all there is nothing to see by. Eyes need light bouncing off the thing."]},{std:["1-PS4-3"],n:4,dur:90,dir:"Look at the test results. Answer out loud.",desc:"using test results to tell what happens when different materials are put in the path of a beam of light",html:()=>`<p class="big">One flashlight beam was pointed at four things in the dark tent and what it did was written down.</p>
     <table class="bigTable"><tr><th>What was put in the beam</th><th>What the beam did</th></tr>
     <tr><td>a clear slab of ice</td><td>went through, slightly bent</td></tr>
     <tr><td>the canvas tent wall</td><td>a faint glow came through</td></tr>
     <tr><td>a wooden crate lid</td><td>stopped, and made a dark shadow</td></tr>
     <tr><td>a polished steel plate</td><td>bounced away at an angle</td></tr></table>`,qs:["Which of the four let the most light through?","Which thing let none through at all?","Someone outside the tent at night can see a faint glow through the canvas but cannot tell who is inside. Use the chart to explain why.","The team wants to light up a dark corner of the tent without moving the flashlight. Which of the four would help, and why?"],key:["the clear slab of ice","the wooden crate lid","Canvas only lets a faint glow through. Some light gets out, but not enough of it in a clear picture to show a shape.","the polished steel plate, because it bounces the beam off in a new direction and can send it into the corner."]}]},{id:27,title:"Camp to the Ridge",short:"Signals",parts:[{std:["1-PS4-4"],n:3,dur:90,dir:"Draw your answer on your paper. Then answer out loud.",desc:"designing a device that uses light or sound to send a message over a distance too far to shout",html:()=>`<p class="big">Two of the team are up on the ridge, far above the camp. The wind takes away a shout before it gets halfway.</p>
     <div class="figure">${ic("mountain",88)}${ic("lamp",88)}${ic("megaphone",88)}</div>`,qs:["Draw a device at the camp that tells the pair on the ridge that supper is ready. It has to use light or sound.","Describe your device to me and tell me whether light or sound carries the message.","The pair on the ridge need a way to answer back. Draw or describe what they would carry, and say how the camp will know what their answer means."],key:["Any device that carries light or sound up the slope: a lamp raised on a pole, a lamp flashed on and off, a horn, a bell, a whistle, a mirror catching the sun.","Names it and says which one it uses.","Anything small enough to carry that makes light or sound, with an agreed meaning: one whistle means we heard you, two flashes means we are coming down. The agreement is what makes it a message."]}]},{id:28,title:"Fix the Frozen Bottles",short:"Fix It",parts:[{std:["K-2-ETS1-1"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"naming a problem people want to change, asking a question about it, and saying what to observe first",read:"Every evening the team fills the water bottles and leaves them in the supply tent. Every morning at least half the bottles are frozen solid, and a frozen bottle is no use until somebody warms it up, which takes a long time.",qs:["What is the problem the team wants to change?","Ask me one question that would tell you more about why it happens.","What would you measure first, before you made anything?"],key:["The water bottles freeze overnight in the supply tent.","Any real question: how cold does the tent get, how many bottles freeze, where in the tent are they kept, how full are the bottles, how long does it take. A statement is not a question, so ask once more.","Any real observation: count how many froze, measure the temperature in the tent, check whether the ones near the middle froze less, note how long they sat out."]},{std:["K-2-ETS1-2"],n:3,dur:90,dir:"Draw your answer on your paper and hold it up. Then answer out loud.",desc:"making a simple drawing of a fix and explaining how the shape of the object makes it work",html:()=>`<p class="big">Draw something that keeps the water bottles from freezing in the night.</p>
     <div class="figure">${ic("drop",88)}${ic("pack",88)}${ic("box",88)}</div>`,qs:["Draw what you would make.","Point to the part that keeps the cold out and tell me its shape.","Tell me why that shape works better than standing the bottles up in a line on the floor."],key:["Any real fix: a thick sleeve round each bottle, a padded box they all go in, a bag stuffed with cloth, bottles kept inside a sleeping bag, bottles packed close together under a blanket.","Names a shape: a thick wrap all the way round, a deep padded box, a closed bag, a tight bundle.","Because a thick layer all the way round slows the cold reaching the water. Bottles standing alone on a cold floor have nothing between them and the cold."]}]},{id:29,title:"Which Sleeve Worked",short:"Test Data",parts:[{std:["K-2-ETS1-3"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"comparing the data from tests of two objects built to solve the same problem",html:()=>`<p class="big">Two bottle sleeves were tested on the same night, eight bottles in each.</p>
     <table class="bigTable"><tr><th>Sleeve</th><th>Bottles frozen by morning, out of 8</th></tr>
     <tr><td>a thick wool sleeve</td><td>1</td></tr>
     <tr><td>a thin plastic sleeve</td><td>6</td></tr></table>`,qs:["Which sleeve worked better in the test?","Which numbers in the chart make you say that?","Both sets of bottles were left out on the same night. Why does testing them on the same night make the comparison fair?"],key:["the thick wool sleeve","Only 1 bottle out of 8 froze in the wool sleeve and 6 out of 8 froze in the plastic one. The numbers have to be in the answer.","Because the cold was the same for both. If one set had been left out on a warmer night you would not know whether the sleeve or the weather made the difference."]}]},{id:30,title:"The Camp Agreement",short:"Rights",parts:[{std:["HSS-1.1"],n:4,dur:90,dir:"Listen while your teacher reads. Then answer out loud.",desc:"telling a right from a responsibility and connecting the agreement of a small group to the rules of a town",read:"On the first day the team wrote an agreement and everyone signed it. It says that every person gets a hot meal, a dry place to sleep, and a turn to speak at the morning meeting. It also says that every person writes their own gear into the log before they go out, and that nobody goes past the flag line on their own.",qs:["Name one thing from the agreement that every person gets.","Name one thing from the agreement that every person has to do.","The rule about not going past the flag line on your own protects somebody. Who does it protect?","A town has rules too, and the people in a town did not all sign a paper. Name one rule in a town and say who it keeps safe."],key:["A hot meal, a dry place to sleep, or a turn to speak at the morning meeting. Those are the rights.","Writing their own gear into the log, or not going past the flag line alone. Those are the responsibilities.","Everybody, including the person themselves. Any answer about keeping people safe counts.","Any real rule with who it protects: stopping at a red light keeps drivers and walkers safe, keeping dogs on a lead keeps other people safe, no swimming where there is no guard."]}]},{id:31,title:"The Camp Map",short:"Map Grid",parts:[{std:["HSS-1.2"],n:4,dur:90,dir:"Look at the map grid. Answer out loud.",desc:"giving an exact grid location, describing a relative location, and telling a physical feature from a built one",html:()=>`<p class="big">A map of the camp, drawn on a grid.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("mountain",56)}</td><td></td><td>${ic("wave",56)}</td></tr>
     <tr><th>B</th><td>${ic("tent",56)}</td><td>${ic("tent",56)}</td><td></td></tr>
     <tr><th>C</th><td></td><td>${ic("flag",56)}</td><td>${ic("box",56)}</td></tr></table>
     <p class="big">${ic("mountain",48)} the ice ridge &nbsp; ${ic("wave",48)} the bay &nbsp; ${ic("tent",48)} the tents &nbsp; ${ic("flag",48)} the flag line &nbsp; ${ic("box",48)} the supply store</p>
     <p class="big">The top of this map is north. The bottom is south, the right is east, and the left is west.</p>
     <p class="big">The team also carries a globe, a round model of the whole Earth, and a flat photograph of this bay taken from a plane.</p>`,qs:["Find the supply store. Give its exact spot on the grid, the letter and the number.","Where is the bay compared to the supply store? Use north, south, east or west.","The team has a round globe of the whole Earth and a flat photograph of this one bay. Name one thing the globe shows you that the photograph cannot.","Name two things on this map that the team put there."],key:["C3. Both parts are needed.","North of the supply store. The student may add that it is in the same column, which is a strong answer.","The globe is round like the real Earth and shows the whole world at once, all seven continents and all four oceans, and how far apart two places are. The photograph shows only this one bay from one side. Any true difference counts. (HSS-1.2)","The tents, the flag line, or the supply store."]},{std:["HSS-1.5"],n:3,dur:75,dir:"Answer out loud.",desc:"naming built features of a familiar place and recognizing that people in one place come from many different places",html:()=>`<p class="big">Ten people are at this camp. They grew up in seven different states. Two grew up in other countries. At supper they each told the others. Each one named one food from home.</p>
     <p class="big">Every person at camp has one job. Each one does it well. One cooks. One mends the machines. One keeps the radio working. One looks after the dogs. Back home their families are working too. They are cooking the meals. They are washing the clothes. They are looking after the children. Nobody even pays them for it.</p>
     <div class="figure">${ic("tent",88)}${ic("soup",88)}${ic("globe",88)}</div>`,qs:["Do the people working side by side at this camp all come from the same place? Say how you know.","Think of the place you live. Name three things there that people built, and say what one of them does for the people who live there.","Each person at camp does one special job instead of all of them. Why does that work better? Then name one job somebody does at home that nobody gets paid for but everybody needs."],key:["No. They grew up in seven different states and two other countries.","Any three built things, with a use for one: a school teaches children, a hospital takes care of sick people, a store sells food, a road lets people travel, a park gives a place to play.","Each person gets good at their own job and can do it faster and better than somebody doing everything, and between them all the jobs get done. For the second part, any real unpaid job in a home: cooking, washing clothes, cleaning, looking after a child, looking after an older relative, shopping for food, fixing things. Both parts are what is being checked. (HSS-1.5)"]}]},{id:32,title:"Symbols, Then and Now",short:"Symbols",parts:[{std:["HSS-1.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling why a country keeps one shared symbol and naming a custom that goes with it",html:()=>`<p class="big">The team carried a flag with them. It was a United States flag. They put it up outside. It went outside the main tent. The same flag flies outside post offices. It flies outside schools and courthouses. It flies all over the country.</p>
     <p class="big">The country also keeps famous papers safe. The Declaration of Independence was written in 1776. It is a paper. It said this country would decide. The country would make its own decisions. Instead nobody would be ruling it. No country far away would.</p>
     <div class="figure">${ic("flag",110)}${ic("tent",96)}</div>`,qs:["The country keeps a famous paper from 1776 safe. What is it called, and what did it say?","Why would a team working far from home carry the flag of their country with them?","There are customs for taking care of a flag. It is folded a certain way and it is not meant to touch the ground. Why would people make careful rules for a piece of cloth?"],key:["The Declaration of Independence. It said this country would make its own decisions instead of being ruled from far away. Accept that it is the paper that started our country. (HSS-1.3)","To show where they come from, and because the flag stands for their country even when they are far away.","Because of what it stands for. People take care of the flag the way they would take care of the idea behind it, not because the cloth itself is special."]},{std:["HSS-1.4"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing everyday life long ago with life today and telling what changed from what stayed the same",html:()=>`<p class="big">Sending word home from somewhere far away.</p>
     <table class="bigTable"><tr><th></th><th>Long ago</th><th>Today</th></tr>
     <tr><td>how word traveled</td><td>a letter carried by ship</td><td>a radio or a satellite call</td></tr>
     <tr><td>how long it took</td><td>many weeks</td><td>a few seconds</td></tr>
     <tr><td>why people sent it</td><td>to tell their family they were well</td><td>to tell their family they were well</td></tr></table>
     <div class="figure">${ic("radio",88)}${ic("sailboat",88)}</div>`,qs:["Long ago, how did word from a far away team get home?","How does word get home today?","Name something on the chart that people do differently now.","Name something on the chart that has not changed at all."],key:["A letter carried by ship, taking many weeks.","By radio or a satellite call, in a few seconds.","How word traveled changed, or how long it took changed. Either counts.","Why people sent it: to tell their family they were well. That is the half of the standard that is easy to miss, so it is asked on its own."]}]}];const LEVELUPS={3:{id:"L3",lv:true,title:"Level Up: Longer Words",std:["RF.2.3"],needs:["RF.1.3"],n:3,dir:"Read each word out loud.",html:()=>`<div style="text-align:center">${["sunlight","unpack","coldest"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["sunlight (two syllables, compound word)","unpack (prefix un-)","coldest (suffix -est)"]},5:{id:"L5",lv:true,title:"Level Up: Thick Ice Read",std:["RF.2.4"],needs:["RF.1.4"],n:60,label:"words read correctly",dir:"Read this harder story out loud in your best reading voice.",html:()=>`<p class="passage">${ICETHICK}</p>`,key:["60 words. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Note pace and expression. A grade 2 reader should group the words into phrases, not read one word at a time.","Quick check after reading: Why did the leader put out orange flags? (to show where the ice was too thin for a sled)"]},6:{id:"L6",lv:true,title:"Level Up: Two-Step Problem",std:["2.OA.A.1"],needs:["1.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">The team packed 36 bags of dog food. The ship brought 25 more bags. Then the dogs ate 8 bags. How many bags are left?</p>`,key:["53 bags (36 + 25 = 61, then 61 - 8 = 53)"]},7:{id:"L7",lv:true,title:"Level Up: Why and How",std:["RL.2.1"],needs:["RL.1.1"],n:2,dir:"Answer out loud. Use the story.",html:()=>`<p class="passage" style="font-size:1.5rem">${HAT}</p><ol class="qlist"><li>Why did Rosa run over to Pim?</li><li>How did Pim get his hat back?</li></ol>`,key:["The wind had taken his hat, so he needed help to find it. Accept: to help him look","He dug in the soft snow by the tents and then looked under a crate, where the hat was"]},9:{id:"L9",lv:true,title:"Level Up: Seal Science",std:["RI.2.1"],needs:["RI.1.1"],n:2,dir:"Answer out loud. Use the text.",html:()=>`<p class="passage" style="font-size:1.5rem">${SEALS}</p><ol class="qlist"><li>Why does a seal need to find a hole in the ice?</li><li>How does a seal stay warm in such cold water?</li></ol>`,key:["It has to breathe. It can hold its breath for a long time, but it must come up for air","Its thick layer of fat holds in the heat"]}};const PASSAGE_STD=["RL.1.1","RI.1.1","RL.2.1","RI.2.1","1-LS1-1","1-LS1-2","1-LS3-1","1-ESS1-1","1-ESS1-2","1-PS4-1","1-PS4-2","1-PS4-3","1-PS4-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-1.1","HSS-1.2","HSS-1.3","HSS-1.4","HSS-1.5"];let nlOn={},tfOn={},c120On={};function nlHtml(){const marks=Object.keys(nlOn).filter(k=>nlOn[k]).map(Number);return F.numberLine({min:0,max:20,step:1,labelEvery:1,width:680,marks,clickable:true,fluid:true})+`<p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}const STARTERS={opinion:["I would pick ____.","One reason is ____.","It would be ____.","That is why I would pick it."],facts:["My topic is ____.","One fact is ____.","Another fact is ____.","That is what a polar camp is like."],story:["One day at camp, ____.","First, ____.","Then ____.","After that we ____."]};const SENTSET={"W.1.1":"opinion","W.1.2":"facts","W.1.3":"story","W.1.8":"facts"};const SENTLAB={opinion:"If you are writing what you think:",facts:"If you are writing facts:",story:"If you are telling a story:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const sets=[];parts.forEach(p=>(p.std||[]).forEach(c=>{const k=SENTSET[c];if(k&&STARTERS[k]&&sets.indexOf(k)<0)sets.push(k)}));if(!sets.length){const k=parts[0]&&parts[0].wk;sets.push(STARTERS[k]?k:"opinion")}return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}let tpsBlk=[0,0];function tpsBlkHtml(){return`<div class="blk-row"><button class="chip" data-tb="0" data-td="1">Add a ten</button><button class="chip" data-tb="0" data-td="-1">Take a ten</button><button class="chip" data-tb="1" data-td="1">Add a one</button><button class="chip" data-tb="1" data-td="-1">Take a one</button><button class="chip" data-tb="x">Clear</button></div><div class="tool-scroll" style="text-align:center">${tpsBlk[0]+tpsBlk[1]?F.tens(tpsBlk[0],tpsBlk[1]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${tpsBlk[0]} tens and ${tpsBlk[1]} ones on the mat.</p>`}function tpsBlkBind(b,r){b.querySelectorAll("[data-tb]").forEach(x=>x.onclick=()=>{if(x.dataset.tb==="x")tpsBlk=[0,0];else{const i=+x.dataset.tb;tpsBlk[i]=Math.max(0,Math.min(i?19:9,tpsBlk[i]+ +x.dataset.td))}r()})}F.clockLab=(h,m)=>{const cx=190,cy=190,R=150,pad=n=>String(n).padStart(2,"0");let s=`<svg viewBox="0 0 380 380" width="360" style="max-width:100%;height:auto" role="img" aria-label="Clock face with the hour hand and the minute hand labeled, showing ${h}:${pad(m)}">`;s+=`<circle cx="${cx}" cy="${cy}" r="${R+8}" fill="#F3DCC4" stroke="var(--fig-ink)" stroke-width="4"/><circle cx="${cx}" cy="${cy}" r="${R}" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<60;i++){const a=i*Math.PI/30,l=i%5?6:13;s+=`<line x1="${cx+Math.sin(a)*(R-3)}" y1="${cy-Math.cos(a)*(R-3)}" x2="${cx+Math.sin(a)*(R-3-l)}" y2="${cy-Math.cos(a)*(R-3-l)}" stroke="var(--ink)" stroke-width="${i%5?1.3:2.6}"/>`}for(let i=1;i<=12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*108}" y="${cy-Math.cos(a)*108}" font-size="30" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle" dominant-baseline="central">${i}</text>`}for(let i=0;i<12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*(R+23)}" y="${cy-Math.cos(a)*(R+23)}" font-size="16" font-family="Andika,sans-serif" font-weight="700" fill="var(--sea)" text-anchor="middle" dominant-baseline="central">${i*5}</text>`}const ha=(h%12+m/60)*Math.PI/6,ma=m*Math.PI/30,hl=66,ml=90;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ha)*hl}" y2="${cy-Math.cos(ha)*hl}" stroke="var(--ink)" stroke-width="11" stroke-linecap="round"/><line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ma)*ml}" y2="${cy-Math.cos(ma)*ml}" stroke="var(--sea)" stroke-width="6" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="8" fill="var(--ink)"/>`;const tag=(ang,r,txt,col)=>{let d=ang*180/Math.PI-90;if(d>90||d<-90)d+=180;const x=cx+Math.sin(ang)*r,y=cy-Math.cos(ang)*r;return`<text transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${d.toFixed(1)})" y="-12" font-size="14" font-weight="700" font-family="Andika,sans-serif" fill="${col}" stroke="var(--surface)" stroke-width="3" paint-order="stroke" text-anchor="middle" dominant-baseline="central">${txt}</text>`};s+=tag(ha,38,"hour hand","var(--ink)")+tag(ma,51,"minute hand","var(--sea)");return s+`</svg>`};function tpsClockHtml(){return F.row([F.clockLab(3,0),"3:00, three o'clock"],[F.clockLab(7,30),"7:30, half past seven"])+`<ul class="frames"><li><b>Short hand = hours.</b> Read the big numbers, 1 to 12.</li><li><b>Long hand = minutes.</b> Read the small numbers around the edge. They count by 5s.</li></ul>`+F.table(["Where the long hand points","Minutes","How to write it and say it"],[["straight up at the 12","0 minutes","3:00, three o'clock"],["straight down at the 6","30 minutes","7:30, seven thirty or half past seven"]])+`<ul class="frames"><li>The short hand is the hour. The long hand is the minutes.</li><li>At half past, the short hand sits between two numbers. Say the smaller number.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:70,parts:1,unit:"in",item:4,itemLabel:"pencil"}))+F.table(["Rule","Why it matters"],[["Start at the 0 end","the first unit has to begin where the object begins"],["The units touch, with no gaps","a gap makes the count too small"],["The units do not overlap","an overlap makes the count too big"],["Every unit is the same size","units of different sizes cannot be counted together"]])+`<p class="small">Count the spaces between the marks, not the marks themselves. The pencil above ends at the 4, so it is 4 units long.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["sh, ch, th, wh, ck","two letters, one sound","shop, chin, that, when, duck"],["bl, fl, st, sw, cr","two sounds said close together","flag, stop, swim, crab"],["a_e, i_e, o_e, u_e","the e at the end makes the vowel say its name","cave, bike, note, cube"],["ai, ay, ea, ee, oa, ow","a vowel team: two letters, one vowel sound","rain, day, seal, deep, boat, snow"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, corn, fur"],["-s, -ed, -ing","an ending added to a word","jumps, jumped, jumping"]])+`<ul class="frames"><li>Say each sound, then blend them together. /f/ /l/ /a/ /g/ is flag.</li><li>A long vowel says its name. A short vowel does not.</li><li>Clap the parts: snow-flake is two parts.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who it is about and where they are","First, ____."],["2. Next","what happened in the middle","Next, ____."],["3. Last","how it ended and how you felt","Last, ____."]])+`<ul class="frames"><li>Keep the parts in the order they happened.</li><li>Use the names from the story, not he or she on its own.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Number line to 20",std:["1.MD.A.2","1.MD.B.3","1.MD.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.MD.A.1"],html:nlHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{nlOn[x.dataset.n]=!nlOn[x.dataset.n];r()})},tf:{name:"Ten frames",std:["1.NBT.B.2","1.NBT.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.NBT.A.1"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},chart:{name:"120 chart",std:["1.NBT.A.1","1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","1.OA.C.5","2.NBT.A.1","2.NBT.B.5","2.OA.A.1"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},sent:{name:"Sentence starters",std:["W.1.1","W.1.2","W.1.3","W.1.8"],html:sentHtml},blocks:{name:"Tens and ones blocks",std:["1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","2.NBT.B.5","2.OA.A.1"],html:tpsBlkHtml,bind:tpsBlkBind},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["1.MD.A.2","2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.1.2","RF.1.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.1.1","SL.1.4","W.1.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.1.1","RI.1.1","RL.1.1","SL.1.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.1.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"nl",std:["1.OA.C.5"],msg:"1.OA.C.5 is about counting on and back. With the number line, this stop shows the student can do it with a visual, not in their head."},{t:"nl",std:["1.OA.B.3"],msg:"1.OA.B.3 is about using number tricks (turn-around facts, making ten). If the student counts every hop on the number line, the stop shows counting, not the strategy."},{t:"chart",std:["1.NBT.A.1"],msg:"The 120 chart shows the numerals, so counting, reading, and writing numbers with it open is supported, not independent."},{t:"sent",msg:"Sentence starters supply the opening, the reason frame, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["W.1.1","W.1.2","W.1.8"],msg:"If an adult wrote the words for the student, note it. The writing checks still count, but the printing does not."},{t:"chart",std:["1.NBT.B.2"],msg:"The 120 chart lays the numbers out in rows of ten, so the tens and ones can be read off it. Note that the place value answer was supported."},{t:"chart",std:["1.NBT.C.4","1.NBT.C.6"],msg:"Counting up or down the 120 chart to get the answer shows counting, not the place value strategy this standard asks for. Note which the student did."},{t:"scribe",std:["W.1.3"],msg:"If an adult wrote the story for the student, note it. The story checks still count, but the printing does not."},{t:"clock",std:["1.MD.B.3","2.MD.C.7"],msg:"The clock card names which hand is the hour and what each long hand position is worth, so a time read with it open is supported, not independent."},{t:"ruler",std:["1.MD.A.2","2.MD.A.1"],msg:"The ruler card shows the units already laid end to end from 0 and states the no gaps rule, so count a length found with it open as supported, not independent."},{t:"letters",std:["RF.1.3"],msg:"The letter and sound card lists the patterns and an example word for each, so a word sounded out with it open is supported, not independent."},{t:"letters",std:["RF.1.2"],msg:"RF.1.2 is listening only. If the card was open, note that the student had the blending and long vowel rules in front of them."},{t:"retell",std:["RL.1.1","SL.1.4","W.1.3"],msg:"The card gives the order words first, next and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.1.1","RI.1.1","SL.1.2","L.1.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.1.4"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
